INSERT INTO `electricity_tips` VALUES (1,'Switch to LED Bulbs','LED bulbs use 75% less energy and last 25 times longer than incandescent lighting.','General','bulb-outline','Easy','Low','Student',1,145,0,'2026-05-21 13:42:56'),(2,'Unplug Idle Electronics','Devices in \"standby\" mode still consume power. Unplug chargers and appliances when not in use.','Appliances','bulb-outline','Easy','Low','Student',1,98,0,'2026-05-21 13:42:56'),(3,'Clean Air Filters','Dirty filters make your AC work harder. Clean them monthly to save up to 15% on cooling costs.','Cooling','bulb-outline','Easy','Low','Student',1,131,11,'2026-05-21 13:42:56'),(4,'Wash with Cold Water','Heating water accounts for 90% of the energy used by a washing machine.','Laundry','bulb-outline','Easy','Low','Student',1,208,0,'2026-05-21 13:42:56'),(5,'Use Natural Light','Open your curtains during the day to reduce the need for artificial lighting.','General','bulb-outline','Easy','Low','Student',1,92,1,'2026-05-21 13:42:56');
/*!40000 ALTER TABLE `electricity_tips` ENABLE KEYS */;
UNLOCK TABLES;

